import { readFile } from 'node:fs/promises';
import { decompressSWF } from '../../src/game/assets/swf.mjs';
import { extractSymbols } from '../../src/game/assets/swf-symbols.mjs';
import { buildDisplayList } from '../../src/game/assets/display-list';
import { createSwfLayout } from '../../tools/lib/swf-layout';
import { createSwfLayout as oldLayout } from './old-layout.mts';
import type { SymbolResult } from '../../src/game/assets/asset-pack';

const { bytes } = await decompressSWF(new Uint8Array(await readFile(
  '/home/ian/Projects/ianwijma/documented-bubble-tank-3/re/bt3/uncompressed.swf',
)));
const result = await extractSymbols(bytes, { svg: false }) as unknown as SymbolResult;
if (result.errors.length) throw new Error(result.errors.join('\n'));
const symbols = result.symbols, current = createSwfLayout(symbols), previous = oldLayout(symbols);
const ids = new Set(symbols.morphs.map((m) => m.id));
const confirmation = symbols.sprites.find((s) => s.id === 915)!;
const frames = [2, 7, 12, 17, 22].map((frame) => {
  const old = previous.collect(915, frame, 'up'), leaves = current.collect(915, frame, 'up');
  return {
    frame,
    authoredMorphs: buildDisplayList(confirmation, frame)
      .filter((p) => ids.has(p.charId)).map((p) => ({ id: p.charId, ratio: p.ratio ?? 0 })),
    previousLeaves: old.length,
    currentLeaves: leaves.length,
    morphMetadata: leaves.filter((p) => ids.has(p.id)).map((p) => ({
      id: p.id, bounds: p.bounds, fill: p.fill, stroke: p.stroke,
    })),
  };
});
