});
test('numeric layout composes parent and child matrices before bounding the morphed leaf', () => {
  const parent = { a: 0, b: 2, c: -3, d: 0, tx: 100, ty: 200 },
    child = { a: 2, b: 0, c: 0, d: 0.5, tx: 40, ty: 60 },
    importer = layout([
