      {
        id: 12,
        frameCount: 1,
        placements: [{ frame: 1, depth: 1, charId: 1, matrix: identity, ratio: 65535 }],
      },
    ]),
    matrix = { a: 0, b: 4, c: -1.5, d: 0, tx: -80, ty: 280 };
  expect(importer.multiply(parent, child)).toEqual(matrix);
